sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Add your code here
	try{
		gs.info("[Table Integration POST]" +
			"\nopened_by: " + current.opened_by+
			"\nrequestor: " + current.requestor+
			"\ntype_of_asset: " + current.type_of_asset+
			"\nconsumables: " + current.consumables+
			"\ncompany: " + current.company+
			"\npriority: " + current.priority+
			"\nshort_description: " + current.short_description+
			"\ndescription: " + current.description+
			"\ncorrelation_id: " + current.getUniqueValue());


		var request = new sn_ws.RESTMessageV2('Table API Instance A to B', 'POST Method');
		var payLoad = {
			"opened_by": current.opened_by.toString(),
			"requestor": current.requestor.toString(),
			"type_of_asset": current.type_of_asset.toString(),
			"consumables": current.consumables.toString(),
			"company": current.company.toString(),
			"priority": current.priority.toString(),
			"short_description": current.short_description.toString(),
			"description": current.description.toString(),
			'correlation_id': current.getUniqueValue()
		};

		request.setRequestBody(JSON.stringify(payLoad));

		var response = request.execute();
		var httpStatus = response.getStatusCode();
		var responseBody = response.getBody();

		if (httpStatus == 201) {
            gs.info("[Table Integration POST] Successfully created record in Instance B. Status: 201");

			var parsedJson = JSON.parse(responseBody);
			var targetSysId = parsedJson.result.sys_id;

			gs.info("[Table Integration POST] Instance B Record SysID: " + targetSysId);
			// current.correlation_id = targetSysId;

			if(targetSysId){
				var gr = new GlideRecord(current.getTableName());
				if(gr.get(current.getUniqueValue())){
					gr.setValue('correlation_id', targetSysId);
					gr.setWorkflow(false);
					gr.update();
				}
			}
        } 
		else {
            gs.error("[Table Integration POST] Failed to create record in Instance B. Status: " + httpStatus + " Response: " + response.getBody());
        }
	}
	catch(ex){
		gs.error("[Table Integration POST] Instance B Integration Error: " + ex.getMessage());
	}



})(current, previous);
